   return buffer_size - (rd_idx - wr_idx);
 }

+static uint16_t sf32lb52_bt_diag_get_le16(const uint8_t *data)
+{
+  return (uint16_t)data[0] | ((uint16_t)data[1] << 8);
+}
+
+static uint32_t sf32lb52_bt_diag_get_le32(const uint8_t *data)
+{
+  return (uint32_t)data[0] | ((uint32_t)data[1] << 8) |
+         ((uint32_t)data[2] << 16) | ((uint32_t)data[3] << 24);
+}
+
+static int sf32lb52_bt_diag_h4_packet_len(const uint8_t *data, size_t len)
+{
+  if (len < 1)
+    {
+      return 0;
+    }
+
+  switch (data[0])
+    {
+      case H4_EVT:
+        return len < 3 ? 0 : 3 + data[2];
+
+      case H4_ACL:
+      case H4_ISO:
+        return len < 5 ? 0 :
+               5 + (sf32lb52_bt_diag_get_le16(&data[3]) &
+                    (data[0] == H4_ISO ? 0x3fff : 0xffff));
+
+      case H4_CMD:
+        return len < 4 ? 0 : 4 + data[3];
+
+      case H4_SCO:
+        return len < 4 ? 0 : 4 + data[3];
+
+      default:
+        return -EINVAL;
+    }
+}
+
+static void sf32lb52_bt_diag_acl_data_rx(const uint8_t *data, size_t len)
+{
+  struct sf32lb52_bt_rx_diag_s *diag = &g_sf32lb52_bt_rx_diag;
+  uint16_t handle_flags;
+  uint16_t handle;
+  uint16_t payload_len;
+  uint8_t pb;
+
+  if (len < 5 || data[0] != H4_ACL)
+    {
+      return;
+    }
+
+  handle_flags = sf32lb52_bt_diag_get_le16(&data[1]);
+  handle = handle_flags & 0x0fff;
+  pb = (handle_flags >> 12) & 0x03;
+  payload_len = sf32lb52_bt_diag_get_le16(&data[3]);
+
+  if (len < 5 + payload_len)
+    {
+      return;
+    }
+
+  if (pb == BT_HCI_ACL_CONTINUATION)
+    {
+      if (!diag->data_active || handle != diag->data_handle)
+        {
+          return;
+        }
+
+      diag->data_accumulated += payload_len;
+      syslog(LOG_INFO,
+             "sf32lb52 adapter ACL DATA RX: seq=%lu handle=0x%04x "
+             "pb=%u fragment=continuation payload=%u accumulated=%lu/%lu\n",
+             (unsigned long)diag->data_seq, handle, pb, payload_len,
+             (unsigned long)diag->data_accumulated,
+             (unsigned long)diag->data_expected);
+    }
+  else
+    {
+      uint16_t l2cap_len;
+
+      diag->data_active = false;
+      if (payload_len < 12 ||
+          sf32lb52_bt_diag_get_le16(&data[7]) != 0x0004 ||
+          data[9] != 0x12 ||
+          sf32lb52_bt_diag_get_le16(&data[10]) != 0x0010 ||
+          data[12] != 0x11)
+        {
+          return;
+        }
+
+      l2cap_len = sf32lb52_bt_diag_get_le16(&data[5]);
+      diag->data_active = true;
+      diag->data_handle = handle;
+      diag->data_seq = sf32lb52_bt_diag_get_le32(&data[13]);
+      diag->data_accumulated = payload_len;
+      diag->data_expected = 4 + l2cap_len;
+      syslog(LOG_INFO,
+             "sf32lb52 adapter ACL DATA RX: seq=%lu handle=0x%04x "
+             "pb=%u fragment=start payload=%u accumulated=%lu/%lu\n",
+             (unsigned long)diag->data_seq, handle, pb, payload_len,
+             (unsigned long)diag->data_accumulated,
+             (unsigned long)diag->data_expected);
+    }
+
+  if (diag->data_active &&
+      diag->data_accumulated >= diag->data_expected)
+    {
+      syslog(LOG_INFO,
+             "sf32lb52 adapter ACL DATA RX: seq=%lu handle=0x%04x "
+             "complete accumulated=%lu/%lu\n",
+             (unsigned long)diag->data_seq, diag->data_handle,
+             (unsigned long)diag->data_accumulated,
+             (unsigned long)diag->data_expected);
+      diag->data_active = false;
+    }
+}
+
+static void sf32lb52_bt_diag_rx_feed(const uint8_t *data, size_t len)
+{
+  struct sf32lb52_bt_rx_diag_s *diag = &g_sf32lb52_bt_rx_diag;
+  size_t i;
+
+  for (i = 0; i < len; i++)
+    {
+      int packet_len;
+
+      if (diag->packet_len == sizeof(diag->packet))
+        {
+          diag->packet_len = 0;
+        }
+
+      diag->packet[diag->packet_len++] = data[i];
+
+      for (;;)
+        {
+          packet_len = sf32lb52_bt_diag_h4_packet_len(diag->packet,
+                                                       diag->packet_len);
+          if (packet_len == 0)
+            {
+              break;
+            }
+
+          if (packet_len < 0 || packet_len > sizeof(diag->packet))
+            {
+              memmove(diag->packet, &diag->packet[1],
+                      --diag->packet_len);
+              continue;
+            }
+
+          if ((size_t)packet_len > diag->packet_len)
+            {
+              break;
+            }
+
+          if (diag->packet[0] == H4_ACL)
+            {
+              sf32lb52_bt_diag_acl_data_rx(diag->packet, packet_len);
+            }
+
+          diag->packet_len -= packet_len;
+          memmove(diag->packet, &diag->packet[packet_len],
+                  diag->packet_len);
+        }
+    }
+}
