@@ -555,6 +744,8 @@ static int32_t sf32lb52_bt_rx_ind(ipc_queue_handle_t handle, size_t size)
   struct sf32lb52_bt_env_s *env = &g_sf32lb52_bt_env;
   irqstate_t flags;
