@@ -574,13 +765,26 @@ static int32_t sf32lb52_bt_rx_ind(ipc_queue_handle_t handle, size_t size)

   flags = enter_critical_section();
   env->rx_work_pending = true;
-  queue_work = !env->rx_worker_running && work_available(&env->rx_work);
+  work_ready = work_available(&env->rx_work);
+  queue_work = !env->rx_worker_running && work_ready;
   if (queue_work)
     {
       env->rx_worker_running = true;
+      env->rx_exit_window_reported = false;
+    }
+  else if (!env->rx_worker_running && !work_ready &&
+           !env->rx_exit_window_reported)
+    {
+      env->rx_exit_window_reported = true;
+      report_exit_window = true;
     }
   leave_critical_section(flags);

+  if (report_exit_window)
+    {
+      syslog(LOG_WARNING, "sf32lb52 bt RX worker exit window hit\n");
+    }
