+#if SF32LB52_BT_TRACE
+static void sf32lb52_bt_trace_h4_fragment(uint16_t rx_len,
+                                          const uint8_t *data,
+                                          size_t pending,
+                                          ssize_t expected)
+{
+  char bytes[3 * 8];
+  size_t shown = pending < 8 ? pending : 8;
+  size_t offset = 0;
+  size_t i;
+
+  bytes[0] = '\0';
+  for (i = 0; i < shown; i++)
+    {
+      offset += snprintf(&bytes[offset], sizeof(bytes) - offset,
+                         i == 0 ? "%02x" : " %02x", data[i]);
+    }
+
+  syslog(LOG_INFO,
+         "sf32lb52 bth4 h4 fragment/drop: rx_len=%u pending=%lu "
+         "expected=%ld first=%s\n",
+         rx_len, (unsigned long)pending, (long)expected, bytes);
+}
+#endif
