+static void sf32lb52_bt_diag_acl_data_rx(const uint8_t *data, size_t len)
+{
+  struct sf32lb52_bt_rx_diag_s *diag = &g_sf32lb52_bt_rx_diag;
+  uint16_t handle_flags;
+  uint16_t handle;
+  uint16_t payload_len;
+  uint8_t pb;
+
+  if (len < 5 || data[0] != H4_ACL)
+    {
+      return;
+    }
+
+  handle_flags = sf32lb52_bt_diag_get_le16(&data[1]);
+  handle = handle_flags & 0x0fff;
+  pb = (handle_flags >> 12) & 0x03;
+  payload_len = sf32lb52_bt_diag_get_le16(&data[3]);
+
+  if (len < 5 + payload_len)
+    {
+      return;
+    }
+
+  if (pb == BT_HCI_ACL_CONTINUATION)
+    {
+      if (!diag->data_active || handle != diag->data_handle)
+        {
+          return;
+        }
+
+      diag->data_accumulated += payload_len;
+      syslog(LOG_INFO,
+             "sf32lb52 adapter ACL DATA RX: seq=%lu handle=0x%04x "
+             "pb=%u fragment=continuation payload=%u accumulated=%lu/%lu\n",
+             (unsigned long)diag->data_seq, handle, pb, payload_len,
+             (unsigned long)diag->data_accumulated,
+             (unsigned long)diag->data_expected);
+    }
+  else
+    {
+      uint16_t l2cap_len;
+
+      diag->data_active = false;
+      if (payload_len < 12 ||
+          sf32lb52_bt_diag_get_le16(&data[7]) != 0x0004 ||
+          data[9] != 0x12 ||
+          sf32lb52_bt_diag_get_le16(&data[10]) != 0x0010 ||
+          data[12] != 0x11)
+        {
+          return;
+        }
+
+      l2cap_len = sf32lb52_bt_diag_get_le16(&data[5]);
+      diag->data_active = true;
+      diag->data_handle = handle;
+      diag->data_seq = sf32lb52_bt_diag_get_le32(&data[13]);
+      diag->data_accumulated = payload_len;
+      diag->data_expected = 4 + l2cap_len;
+      syslog(LOG_INFO,
+             "sf32lb52 adapter ACL DATA RX: seq=%lu handle=0x%04x "
+             "pb=%u fragment=start payload=%u accumulated=%lu/%lu\n",
+             (unsigned long)diag->data_seq, handle, pb, payload_len,
+             (unsigned long)diag->data_accumulated,
+             (unsigned long)diag->data_expected);
+    }
+
+  if (diag->data_active &&
+      diag->data_accumulated >= diag->data_expected)
+    {
+      syslog(LOG_INFO,
+             "sf32lb52 adapter ACL DATA RX: seq=%lu handle=0x%04x "
+             "complete accumulated=%lu/%lu\n",
+             (unsigned long)diag->data_seq, diag->data_handle,
+             (unsigned long)diag->data_accumulated,
+             (unsigned long)diag->data_expected);
+      diag->data_active = false;
+    }
+}
