+static void sf32lb52_bt_trace_att(const char *direction,
+                                  const uint8_t *data, size_t len)
+{
+  const size_t att_offset = H4_HEADER_SIZE +
+                            sizeof(struct bt_hci_acl_hdr_s) + 4;
+  uint16_t handle_flags;
+  uint16_t acl_len;
+  uint16_t l2cap_len;
+  uint16_t cid;
+  size_t att_len;
+
+  if (len <= att_offset || data[0] != H4_ACL)
+    {
+      return;
+    }
+
+  handle_flags = sf32lb52_bt_get_le16(&data[H4_HEADER_SIZE]);
+  if (((handle_flags >> 12) & 0x3) == 0x1)
+    {
+      return;
+    }
+
+  acl_len = sf32lb52_bt_get_le16(&data[H4_HEADER_SIZE + 2]);
+  if (acl_len < 5)
+    {
+      return;
+    }
+
+  l2cap_len = sf32lb52_bt_get_le16(
+    &data[H4_HEADER_SIZE + sizeof(struct bt_hci_acl_hdr_s)]);
+  cid = sf32lb52_bt_get_le16(
+    &data[H4_HEADER_SIZE + sizeof(struct bt_hci_acl_hdr_s) + 2]);
+  if (cid != 0x0004)
+    {
+      return;
+    }
+
+  att_len = acl_len - 4;
+  if (att_len > l2cap_len)
+    {
+      att_len = l2cap_len;
+    }
+
+  if (att_len > len - att_offset)
+    {
+      att_len = len - att_offset;
+    }
+
+  if (att_len == 0)
+    {
+      return;
+    }
+
+  syslog(LOG_INFO,
+         "sf32lb52 bth4 ATT %s: opcode=0x%02x h4_len=%lu att_len=%lu "
+         "data=%02x %02x %02x %02x %02x %02x %02x %02x\n",
+         direction, data[att_offset], (unsigned long)len,
+         (unsigned long)att_len,
+         data[att_offset],
+         att_len > 1 ? data[att_offset + 1] : 0,
+         att_len > 2 ? data[att_offset + 2] : 0,
+         att_len > 3 ? data[att_offset + 3] : 0,
+         att_len > 4 ? data[att_offset + 4] : 0,
+         att_len > 5 ? data[att_offset + 5] : 0,
+         att_len > 6 ? data[att_offset + 6] : 0,
+         att_len > 7 ? data[att_offset + 7] : 0);
+}
