+static void sf32lb52_bt_trace_acl_data_rx(const uint8_t *data, size_t len)
+{
+  const size_t acl_offset = H4_HEADER_SIZE;
+  const size_t l2cap_offset =
+    H4_HEADER_SIZE + sizeof(struct bt_hci_acl_hdr_s);
+  const size_t att_offset = l2cap_offset + 4;
+  struct sf32lb52_bt_acl_data_trace_s *trace =
+    &g_sf32lb52_bt_acl_data_trace;
+  uint16_t handle_flags;
+  uint16_t handle;
+  uint16_t acl_len;
+  uint8_t pb;
+
+  if (data[0] != H4_ACL ||
+      len < H4_HEADER_SIZE + sizeof(struct bt_hci_acl_hdr_s))
+    {
+      return;
+    }
+
+  handle_flags = sf32lb52_bt_get_le16(&data[acl_offset]);
+  handle = handle_flags & 0x0fff;
+  pb = (handle_flags >> 12) & 0x03;
+  acl_len = sf32lb52_bt_get_le16(&data[acl_offset + 2]);
+  if (len < l2cap_offset + acl_len)
+    {
+      return;
+    }
+
+  if (pb == BT_HCI_ACL_CONTINUATION)
+    {
+      if (!trace->active || trace->handle != handle)
+        {
+          return;
+        }
+
+      trace->accumulated += acl_len;
+      syslog(LOG_INFO,
+             "sf32lb52 bth4 ACL DATA RX: seq=%lu handle=0x%04x "
+             "pb=%u fragment=continuation payload=%u accumulated=%lu/%lu\n",
+             (unsigned long)trace->seq, handle, pb, acl_len,
+             (unsigned long)trace->accumulated,
+             (unsigned long)trace->expected);
+
+      if (trace->accumulated >= trace->expected)
+        {
+          syslog(LOG_INFO,
+                 "sf32lb52 bth4 ACL DATA RX: seq=%lu handle=0x%04x "
+                 "complete accumulated=%lu/%lu\n",
+                 (unsigned long)trace->seq, handle,
+                 (unsigned long)trace->accumulated,
+                 (unsigned long)trace->expected);
+          trace->active = false;
+        }
+
+      return;
+    }
+
+  if (acl_len < 12 || len < att_offset + 8 ||
+      sf32lb52_bt_get_le16(&data[l2cap_offset + 2]) != 0x0004 ||
+      data[att_offset] != 0x12 ||
+      sf32lb52_bt_get_le16(&data[att_offset + 1]) != 0x0010 ||
+      data[att_offset + 3] != 0x11)
+    {
+      if (trace->active && trace->handle == handle)
+        {
+          trace->active = false;
+        }
+
+      return;
+    }
+
+  if (trace->active && trace->accumulated < trace->expected)
+    {
+      syslog(LOG_INFO,
+             "sf32lb52 bth4 ACL DATA RX: seq=%lu handle=0x%04x "
+             "previous incomplete accumulated=%lu/%lu\n",
+             (unsigned long)trace->seq, trace->handle,
+             (unsigned long)trace->accumulated,
+             (unsigned long)trace->expected);
+    }
+
+  trace->active = true;
+  trace->handle = handle;
+  trace->seq = (uint32_t)data[att_offset + 4] |
+               ((uint32_t)data[att_offset + 5] << 8) |
+               ((uint32_t)data[att_offset + 6] << 16) |
+               ((uint32_t)data[att_offset + 7] << 24);
+  trace->accumulated = acl_len;
+  trace->expected =
+    (size_t)sf32lb52_bt_get_le16(&data[l2cap_offset]) + 4;
+
+  syslog(LOG_INFO,
+         "sf32lb52 bth4 ACL DATA RX: seq=%lu handle=0x%04x "
+         "pb=%u fragment=start payload=%u accumulated=%lu/%lu\n",
+         (unsigned long)trace->seq, handle, pb, acl_len,
+         (unsigned long)trace->accumulated,
+         (unsigned long)trace->expected);
+
+  if (trace->accumulated >= trace->expected)
+    {
+      syslog(LOG_INFO,
+             "sf32lb52 bth4 ACL DATA RX: seq=%lu handle=0x%04x "
+             "complete accumulated=%lu/%lu\n",
+             (unsigned long)trace->seq, handle,
+             (unsigned long)trace->accumulated,
+             (unsigned long)trace->expected);
+      trace->active = false;
+    }
+}
