+  if (diag->data_active &&
+      diag->data_accumulated >= diag->data_expected)
+    {
+      syslog(LOG_INFO,
+             "sf32lb52 adapter ACL DATA RX: seq=%lu handle=0x%04x "
+             "complete accumulated=%lu/%lu\n",
+             (unsigned long)diag->data_seq, diag->data_handle,
