122	/**
123	 * @brief callback for connected as GATT server.
124	 *
125	 * This callback is triggered when gatts connected. BT Service use this callback to notify the application calling
126	 * bt_gatts_connect that gatts connection has been established.
127	 *
128	 * @param srv_handle - gatts handle(void*). Each GATT service has its own handle.
129	 * @param addr - remote device address.
130	 * @return void.
131	 *
132	 * **Example:**
133	 * @code
134	static void connect_callback(void* srv_handle, bt_address_t* addr)
135	{
136	    PRINT_ADDR("gatts_connect_callback, addr:%s", addr);
137	    add_gatts_device(addr);
138	}
139	 * @endcode
140	 */
141	typedef void (*gatts_connected_cb_t)(gatts_handle_t srv_handle, bt_address_t* addr);
142	
143	/**
144	 * @brief callback for disconnected as GATT server.
145	 *
146	 * This callback is triggered when gatts disconnected. BT Service use this callback to notify the application that
147	 * the gatts connection is destroyed.
148	 *
149	 * @param srv_handle - gatts handle(void*). Each GATT service has its own handle.
150	 * @param addr - remote device address.
151	 * @return void.
152	 *
153	 * **Example:**
154	 * @code
155	static void disconnect_callback(void* srv_handle, bt_address_t* addr)
156	{
157	    gatts_device_t* device = find_gatts_device(addr);
158	    remove_gatts_device(device);
159	    PRINT_ADDR("gatts_disconnect_callback, addr:%s", addr);
160	}
161	 * @endcode
162	 */
163	typedef void (*gatts_disconnected_cb_t)(gatts_handle_t srv_handle, bt_address_t* addr);
164	
165	/**
166	 * @brief callback for Addition of GATT service.
167	 *
168	 * This callback is triggered when GATT server add a GATT service.
169	 *
170	 * @param srv_handle - gatts handle(void*). Each GATT service has its own handle.
171	 * @param status - GATT_STATUS_SUCCESS on success, and other error codes on failure.
172	 * @param attr_handle - attribute handle. The handle identified by each service, not the Attribute handle in spec.
173	 * @return void.
174	 *
175	 * **Example:**
176	 * @code
177	static void attr_table_added_callback(void* srv_handle, gatt_status_t status, uint16_t attr_handle)
178	{
179	    PRINT("gatts add attribute table complete, handle 0x%" PRIx16 ", status:%d", attr_handle, status);
180	}
181	 * @endcode
182	 */
183	typedef void (*gatts_attr_table_added_cb_t)(gatts_handle_t srv_handle, gatt_status_t status, uint16_t attr_handle);
184	
185	/**
186	 * @brief callback for Deletion of GATT service.
187	 *
188	 * This callback is triggered when GATT server remove a GATT service.
189	 *
190	 * @param srv_handle - gatts handle(void*). Each GATT service has its own handle.
191	 * @param status - GATT_STATUS_SUCCESS on success, and other error codes on failure.
192	 * @param attr_handle - attribute handle. The handle identified by each service, not the Attribute handle in spec.
193	 * @return void.
194	 *
195	 * **Example:**
196	 * @code
197	static void attr_table_removed_callback(void* srv_handle, gatt_status_t status, uint16_t attr_handle)
198	{
199	    PRINT("gatts remove attribute table complete, handle 0x%" PRIx16 ", status:%d", attr_handle, status);
200	}
201	 * @endcode
202	 */
203	typedef void (*gatts_attr_table_removed_cb_t)(gatts_handle_t srv_handle, gatt_status_t status, uint16_t attr_handle);
204	
205	/**
206	 * @brief callback for GATT server receive Exchange MTU request.
207	 *
208	 * This callback is triggered as server receive Exchange MTU request from peer GATT client.
209	 * BT Service use this callback to Report the results of MTU negotiation.
210	 *
211	 * @param srv_handle - gatts handle(void*). Each GATT service has its own handle.
212	 * @param addr - remote device address.
213	 * @param mtu - negotiated MTU.
214	 * @return void.
215	 *
216	 * **Example:**
217	 * @code
218	static void mtu_changed_callback(void* srv_handle, bt_address_t* addr, uint32_t mtu)
219	{
220	    gatts_device_t* device = find_gatts_device(addr);
221	    if (device) {
222	        device->gatt_mtu = mtu;
223	    }
224	    PRINT_ADDR("gatts_mtu_changed_callback, addr:%s, mtu:%" PRIu32, addr, mtu);
225	}
226	 * @endcode
227	 */
228	typedef void (*gatts_mtu_changed_cb_t)(gatts_handle_t srv_handle, bt_address_t* addr, uint32_t mtu);
229	
230	/**
231	 * @brief callback for GATT server excute attribute notify operation.
232	 *
233	 * This callback is triggered when GATT server initiate notify to characteristic with property
234	 * contains the notify flag bit.
235	 *
236	 * @param srv_handle - gatts handle(void*). Each GATT service has its own handle.
237	 * @param addr - remote device address.
238	 * @param status - GATT_STATUS_SUCCESS on success, and other error codes on failure.
239	 * @param attr_handle - attribute handle. The handle identified by each service, not the Attribute handle in spec.
240	 * @return void.
241	 *
242	 * **Example:**
243	 * @code
244	static void notify_complete_callback(void* srv_handle, bt_address_t* addr, gatt_status_t status, uint16_t attr_handle)
245	{
246	    if (status != GATT_STATUS_SUCCESS) {
247	        PRINT_ADDR("gatts service notify failed, addr:%s, handle 0x%" PRIx16 ", status:%d", addr, attr_handle, status);
248	        return;
249	    }
250	
251	    if (throughtput_cursor) {
252	        throughtput_cursor--;
253	    } else {
254	        PRINT_ADDR("gatts service notify complete, addr:%s, handle 0x%" PRIx16 ", status:%d", addr, attr_handle, status);
255	    }
256	}
257	 * @endcode
258	 */
259	typedef void (*gatts_nofity_complete_cb_t)(gatts_handle_t srv_handle, bt_address_t* addr, gatt_status_t status, uint16_t attr_handle);
