   475	static int start_advertising(void)
   476	{
   477	  ble_adv_params_t params;
   478	
   479	  if (g_advertiser != NULL)
   480	    {
   481	      return 0;
   482	    }
   483	
   484	  memset(&params, 0, sizeof(params));
   485	  params.adv_type = BT_LE_LEGACY_ADV_IND;
   486	  params.interval = 320;
   487	  params.duration = 0;
   488	  params.channel_map = BT_LE_ADV_CHANNEL_DEFAULT;
   489	  params.filter_policy = BT_LE_ADV_FILTER_WHITE_LIST_FOR_NONE;
   490	
   491	  if (g_adv_data == NULL || g_scan_rsp_data == NULL)
   492	    {
   493	      g_adv_data = advertiser_data_new();
   494	      g_scan_rsp_data = advertiser_data_new();
   495	      if (g_adv_data == NULL || g_scan_rsp_data == NULL)
   496	        {
   497	          printf("openvela_ble_probe: advertiser_data_new failed\n");
   498	          return -1;
   499	        }
   500	
   501	      advertiser_data_set_flags(g_adv_data,
   502	                                BT_AD_FLAG_GENERAL_DISCOVERABLE |
   503	                                BT_AD_FLAG_BREDR_NOT_SUPPORT);
   504	      advertiser_data_set_name(g_scan_rsp_data, "ov_ble_probe");
   505	
   506	      g_adv_payload = advertiser_data_build(g_adv_data,
   507	                                            &g_adv_payload_len);
   508	      g_scan_rsp_payload = advertiser_data_build(g_scan_rsp_data,
   509	                                                 &g_scan_rsp_payload_len);
   510	      if (g_adv_payload == NULL || g_scan_rsp_payload == NULL)
   511	        {
   512	          printf("openvela_ble_probe: advertiser_data_build failed\n");
   513	          return -1;
   514	        }
   515	    }
   516	
   517	  g_advertiser = bt_le_start_advertising(g_instance, &params,
   518	                                         g_adv_payload, g_adv_payload_len,
   519	                                         g_scan_rsp_payload,
   520	                                         g_scan_rsp_payload_len,
   521	                                         &g_advertiser_callbacks);
   522	  if (g_advertiser == NULL)
