   532	int main(int argc, char *argv[])
   533	{
   534	  bt_status_t status;
   535	
   536	  (void)argc;
   537	  (void)argv;
   538	
   539	  sem_init(&g_ble_on_sem, 0, 0);
   540	
   541	  g_instance = bluetooth_create_instance();
   542	  if (g_instance == NULL)
   543	    {
   544	      printf("openvela_ble_probe: bluetooth_create_instance failed\n");
   545	      return 1;
   546	    }
   547	
   548	  if (bt_adapter_register_callback(g_instance, &g_adapter_callbacks) == NULL)
   549	    {
   550	      printf("openvela_ble_probe: callback registration failed\n");
   551	      return 1;
   552	    }
   553	
   554	  status = bt_adapter_enable_le(g_instance);
   555	  if (status != BT_STATUS_SUCCESS && status != BT_STATUS_DONE)
   556	    {
   557	      printf("openvela_ble_probe: bt_adapter_enable_le failed:%d\n",
   558	             status);
   559	      return 1;
   560	    }
   561	
   562	  if (bt_adapter_get_state(g_instance) != BT_ADAPTER_STATE_BLE_ON &&
   563	      bt_adapter_get_state(g_instance) != BT_ADAPTER_STATE_ON)
   564	    {
   565	      printf("openvela_ble_probe: waiting for BLE adapter\n");
   566	      sem_wait(&g_ble_on_sem);
   567	    }
   568	
   569	  if (init_gatt_service() < 0)
   570	    {
   571	      return 1;
   572	    }
   573	
   574	  printf("openvela_ble_probe: delaying advertising 100 ms after GATT "
   575	         "table setup\n");
   576	  usleep(100000);
   577	
   578	  if (start_advertising() < 0)
   579	    {
   580	      return 1;
   581	    }
   582	
   583	  for (;;)
   584	    {
   585	      sleep(60);
   586	    }
   587	}
