const patch = "*** Begin Patch
*** Update File: /home/devbox/project/openvela/apps/examples/openvela_ble_probe/openvela_ble_probe_main.c
@@
 #define PROBE_SERVICE_UUID 0xfff0
 #define PROBE_RX_UUID      0xfff1
 #define PROBE_TX_UUID      0xfff2
+#define MIN_BLE_STARTUP_UPTIME_MS 15000ULL
@@
 static struct probe_throughput_state_s g_throughput;
+
+static int probe_wait_for_ble_startup(void)
+{
+  struct timespec now;
+  uint64_t uptime_ms;
+  uint64_t remaining_ms;
+  uint64_t sleep_ms;
+  bool delay_logged = false;
+
+  for (;;)
+    {
+      if (clock_gettime(CLOCK_MONOTONIC, &now) < 0)
+        {
+          printf("openvela_ble_probe: failed to read system uptime\n");
+          return -1;
+        }
+
+      uptime_ms = (uint64_t)now.tv_sec * 1000u +
+                  (uint64_t)now.tv_nsec / 1000000u;
+      if (uptime_ms >= MIN_BLE_STARTUP_UPTIME_MS)
+        {
+          return 0;
+        }
+
+      remaining_ms = MIN_BLE_STARTUP_UPTIME_MS - uptime_ms;
+      if (!delay_logged)
+        {
+          printf("openvela_ble_probe: delaying BLE start %llu ms "
+                 "for platform readiness\n",
+                 (unsigned long long)remaining_ms);
+          delay_logged = true;
+        }
+
+      sleep_ms = remaining_ms > 100u ? 100u : remaining_ms;
+      usleep((useconds_t)(sleep_ms * 1000u));
+    }
+}

 static uint32_t probe_get_le32(const uint8_t *value)
@@
   (void)argc;
   (void)argv;

+  if (probe_wait_for_ble_startup() < 0)
+    {
+      return 1;
+    }
+
   sem_init(&g_ble_on_sem, 0, 0);
*** End Patch";
text(await tools.apply_patch(patch));

